const items = $input.all();
const rawBody = items[0].json.body || items[0].json;
let body, toolCallId = null;

// Check if this is Vapi tool-calls format
if (rawBody.message && rawBody.message.type === 'tool-calls' && rawBody.message.toolCalls) {
  const toolCall = rawBody.message.toolCalls[0];
  toolCallId = toolCall.id;
  body = toolCall.function.arguments;
} else {
  // Direct format
  body = rawBody;
}

// Required field validation
if (!body.demo_session_id) {
  return [{ json: { valid: false, error: 'Missing required field: demo_session_id', statusCode: 400, toolCallId } }];
}

// UUID format validation
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidRegex.test(body.demo_session_id)) {
  return [{ json: { valid: false, error: 'Invalid demo_session_id format: must be UUID', statusCode: 400, toolCallId } }];
}

// Enum validation
const validStatuses = ['active_call', 'call_ended'];
const validIntents = ['repair_request', 'emergency', 'estimate', 'general_inquiry'];
const validUrgencies = ['emergency', 'urgent', 'routine'];

if (body.status && !validStatuses.includes(body.status)) {
  return [{ json: { valid: false, error: `Invalid status: must be one of ${validStatuses.join(', ')}`, statusCode: 400, toolCallId } }];
}
if (body.intent && !validIntents.includes(body.intent)) {
  return [{ json: { valid: false, error: `Invalid intent: must be one of ${validIntents.join(', ')}`, statusCode: 400, toolCallId } }];
}
if (body.urgency && !validUrgencies.includes(body.urgency)) {
  return [{ json: { valid: false, error: `Invalid urgency: must be one of ${validUrgencies.join(', ')}`, statusCode: 400, toolCallId } }];
}

// Normalize and return
return [{
  json: {
    valid: true,
    toolCallId,
    data: {
      demo_session_id: body.demo_session_id,
      status: body.status || 'active_call',
      name: body.name || null,
      location_city: body.location || body.location_city || null,
      issue: body.issue || null,
      intent: body.intent || 'general_inquiry',
      urgency: body.urgency || 'routine',
      callback_number: body.callback_number || null,
      last_update_ts: new Date().toISOString(),
      final_summary: body.final_summary || body.summary || null,
      control_statement: 'No actions taken without owner approval.'
    }
  }
}];

